'use client';
import { useState, useEffect } from 'react';
import { 
  Shield, Lock, Trash2, Upload, Eye, Printer, ScanLine, 
  Settings, FileText, Clock, HardDrive, FolderOpen,
  AlertTriangle, CheckCircle, XCircle, RefreshCw,
  User, LogOut, Database, Activity
} from 'lucide-react';

type ViewMode = 'customer' | 'owner';

export default function Home() {
  const [viewMode, setViewMode] = useState<ViewMode>('customer');
  const [status, setStatus] = useState('Ready');
  const [sessionInfo, setSessionInfo] = useState<SessionInfo>({
      id: null, startTime: null, totalSize: 0, fileCount: 0
  });
  const [files, setFiles] = useState<FileMetadata[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [endReason, setEndReason] = useState<string | null>(null);
  const [wipeFailures, setWipeFailures] = useState<string[]>([]);
  
  // Owner Mode State
  const [residueFiles, setResidueFiles] = useState<ResidueFile[]>([]);
  const [hasScanned, setHasScanned] = useState(false);
  const [cleanupReport, setCleanupReport] = useState<string | null>(null);
  const [auditLogs, setAuditLogs] = useState<AuditEntry[]>([]);

  useEffect(() => {
    if (window.electronAPI) {
      window.electronAPI.onSessionStatus((_event, value) => {
          setStatus(value);
          if (value.includes('Scann') || value.includes('Print')) setIsProcessing(false); 
      });

      window.electronAPI.onSessionCreated((_event, id) => {
        setStatus('Secure Session Active');
        setFiles([]); 
        setEndReason(null);
        setWipeFailures([]);
      });

      window.electronAPI.onSessionEnded((_event, reason, failures) => {
          setSessionInfo({ id: null, startTime: null, totalSize: 0, fileCount: 0 });
          setFiles([]);
          setStatus('Ready');
          
          if (failures && failures.length > 0) {
              setEndReason('Partial Cleanup - Some files remain locked');
              setWipeFailures(failures);
          } else {
              setEndReason('All data securely destroyed');
              setWipeFailures([]);
          }
      });

      window.electronAPI.onFilesUpdated((_event, newFiles) => {
         setFiles(prev => [...prev, ...newFiles]);
         setStatus(`Imported ${newFiles.length} file(s)`);
         setIsProcessing(false);
      });
      
      window.electronAPI.onSessionInfoUpdated((_event, info) => {
          setSessionInfo(info);
      });
    }
  }, []);

  const handleStartSession = () => {
    if (window.electronAPI) {
      window.electronAPI.startSession();
      setStatus('Starting secure workspace...');
      setWipeFailures([]);
    }
  };

  const handleEndSession = () => {
      if (window.electronAPI && confirm("End this session?\n\nAll files will be permanently destroyed.")) {
        window.electronAPI.endSession();
      }
  };

  const handleImport = () => {
    if (!sessionInfo.id) return;
    setIsProcessing(true);
    window.electronAPI.triggerFileImport();
  };
  
  const handleScan = () => {
    if (!sessionInfo.id) return;
    setIsProcessing(true);
    window.electronAPI.triggerScan();
  };
  
  const handlePrint = (fileName: string) => {
      if (window.electronAPI) {
          window.electronAPI.printFile(fileName);
      }
  };

  const handlePreview = (fileName: string) => {
      if (window.electronAPI) {
          window.electronAPI.previewFile(fileName);
      }
  };
  
  // Owner Mode Handlers
  const handleResidueScan = async () => {
      if (!window.electronAPI) return;
      setIsProcessing(true);
      try {
          const report = await window.electronAPI.scanResidue();
          setResidueFiles(report.foundFiles);
          setHasScanned(true);
          setCleanupReport(null);
      } finally {
          setIsProcessing(false);
      }
  };

  const handleResidueCleanup = async () => {
      if (!window.electronAPI) return;
      
      if (!confirm(`Permanently delete ${residueFiles.length} detected files?`)) {
          return;
      }
      
      setIsProcessing(true);
      try {
          const result = await window.electronAPI.cleanResidue(residueFiles);
          setCleanupReport(`Wiped: ${result.successCount} files`);
          setResidueFiles([]);
          if (result.failures.length > 0) {
              alert(`Some files could not be deleted:\n${result.failures.join('\n')}`);
          }
      } finally {
          setIsProcessing(false);
      }
  };

  const loadAuditLogs = async () => {
      if (!window.electronAPI) return;
      const logs = await window.electronAPI.getAuditLogs();
      setAuditLogs(logs);
  };

  const toggleOwnerMode = () => {
      if (viewMode === 'customer') {
          if (confirm("Enter Owner Mode?\n\nThis shows system maintenance tools.")) {
              setViewMode('owner');
              loadAuditLogs();
          }
      } else {
          setViewMode('customer');
      }
  };
  
  const formatBytes = (bytes: number) => {
      if (bytes === 0) return '0 B';
      const k = 1024;
      const sizes = ['B', 'KB', 'MB', 'GB'];
      const i = Math.floor(Math.log(bytes) / Math.log(k));
      return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const formatTime = (ts: number | null) => {
      if (!ts) return '-';
      return new Date(ts).toLocaleTimeString();
  };

  const formatDate = (ts: number) => {
      const d = new Date(ts);
      return `${d.toLocaleDateString()} ${d.toLocaleTimeString()}`;
  };

  return (
    <div style={{ height: '100vh', display: 'flex', flexDirection: 'column', backgroundColor: '#f5f5f5' }}>
      
      {/* Header */}
      <header style={{ backgroundColor: '#1a1a1a', color: 'white', padding: '16px 30px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
            <Shield size={28} strokeWidth={2} />
            <div>
                <h1 style={{ margin: 0, fontSize: '20px', fontWeight: 600, letterSpacing: '-0.5px' }}>SafeDesk</h1>
                <div style={{ fontSize: '11px', opacity: 0.7, fontWeight: 400 }}>Zero Data Left Behind</div>
            </div>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '20px' }}>
            <div style={{ fontSize: '13px', opacity: 0.9, display: 'flex', alignItems: 'center', gap: '8px' }}>
                {sessionInfo.id ? <><Lock size={16} /> SECURE</> : status}
            </div>
            <button 
                onClick={toggleOwnerMode}
                style={{ background: 'rgba(255,255,255,0.1)', border: '1px solid rgba(255,255,255,0.2)', color: 'white', padding: '8px 16px', borderRadius: '6px', cursor: 'pointer', fontSize: '13px', display: 'flex', alignItems: 'center', gap: '8px', fontWeight: 500 }}>
                {viewMode === 'owner' ? <><User size={16} /> Customer View</> : <><Settings size={16} /> Owner</>}
            </button>
        </div>
      </header>

      {/* Main Content */}
      <main style={{ flex: 1, padding: '30px', display: 'flex', flexDirection: 'column', maxWidth: '1000px', margin: '0 auto', width: '100%', boxSizing: 'border-box', overflowY: 'auto' }}>
        
        {viewMode === 'customer' ? (
            <CustomerView 
                sessionInfo={sessionInfo}
                files={files}
                status={status}
                endReason={endReason}
                wipeFailures={wipeFailures}
                isProcessing={isProcessing}
                onStartSession={handleStartSession}
                onEndSession={handleEndSession}
                onImport={handleImport}
                onScan={handleScan}
                onPreview={handlePreview}
                onPrint={handlePrint}
                formatBytes={formatBytes}
                formatTime={formatTime}
            />
        ) : (
            <OwnerView 
                residueFiles={residueFiles}
                hasScanned={hasScanned}
                cleanupReport={cleanupReport}
                auditLogs={auditLogs}
                isProcessing={isProcessing}
                onResidueScan={handleResidueScan}
                onResidueCleanup={handleResidueCleanup}
                onRefreshLogs={loadAuditLogs}
                formatDate={formatDate}
            />
        )}
      </main>
    </div>
  );
}

// Customer View Component
function CustomerView({ sessionInfo, files, status, endReason, wipeFailures, isProcessing, onStartSession, onEndSession, onImport, onScan, onPreview, onPrint, formatBytes, formatTime }: any) {
    
    if (!sessionInfo.id) {
        return (
            <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: '30px' }}>
                
                {/* Trust Card */}
                <TrustExplanation />

                {/* Status Messages */}
                {endReason && (
                    <div style={{ padding: '20px', background: wipeFailures.length > 0 ? '#fff3cd' : '#d4edda', borderRadius: '8px', border: `1px solid ${wipeFailures.length > 0 ? '#ffc107' : '#28a745'}`, display: 'flex', alignItems: 'center', gap: '12px' }}>
                        {wipeFailures.length > 0 ? <AlertTriangle size={24} color="#856404" /> : <CheckCircle size={24} color="#155724" />}
                        <div style={{ flex: 1 }}>
                            <div style={{ fontSize: '16px', fontWeight: 600, marginBottom: '8px' }}>{endReason}</div>
                            {wipeFailures.length > 0 && (
                                <div style={{ fontSize: '12px', fontFamily: 'monospace', marginTop: '10px', maxHeight: '100px', overflowY: 'auto' }}>
                                    {wipeFailures.map((f: string, i: number) => <div key={i}>• {f}</div>)}
                                </div>
                            )}
                        </div>
                    </div>
                )}

                {/* Start Button */}
                <div style={{ textAlign: 'center', padding: '40px' }}>
                    <button 
                        onClick={onStartSession}
                        disabled={wipeFailures.length > 0}
                        style={{
                            padding: '20px 40px',
                            fontSize: '18px',
                            fontWeight: 600,
                            cursor: wipeFailures.length > 0 ? 'not-allowed' : 'pointer',
                            backgroundColor: wipeFailures.length > 0 ? '#ccc' : '#1a1a1a',
                            color: 'white',
                            border: 'none',
                            borderRadius: '8px',
                            boxShadow: '0 4px 12px rgba(0,0,0,0.15)',
                            display: 'inline-flex',
                            alignItems: 'center',
                            gap: '12px'
                        }}
                    >
                        <Lock size={24} /> Start Secure Session
                    </button>
                </div>
            </div>
        );
    }

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px', flex: 1 }}>
            
            {/* Session Info Bar */}
            <div style={{ display: 'flex', gap: '15px' }}>
                <InfoCard icon={<FileText size={24} />} label="Files" value={sessionInfo.fileCount.toString()} />
                <InfoCard icon={<HardDrive size={24} />} label="Size" value={formatBytes(sessionInfo.totalSize)} />
                <InfoCard icon={<Clock size={24} />} label="Started" value={formatTime(sessionInfo.startTime)} />
            </div>

            {/* Actions */}
            <div style={{ display: 'flex', gap: '10px', justifyContent: 'center', padding: '20px 0' }}>
                <ActionButton icon={<Upload size={20} />} label="Import Files" onClick={onImport} disabled={isProcessing} />
                <ActionButton icon={<ScanLine size={20} />} label="Scan Document" onClick={onScan} disabled={isProcessing} />
                <ActionButton icon={<Trash2 size={20} />} label="End & Destroy" onClick={onEndSession} danger />
            </div>

            {/* File List */}
            <div style={{ flex: 1, background: 'white', borderRadius: '8px', border: '1px solid #e0e0e0', overflow: 'hidden' }}>
                {files.length === 0 ? (
                    <div style={{ padding: '60px', textAlign: 'center', color: '#999' }}>
                        <FolderOpen size={48} style={{ margin: '0 auto 15px', opacity: 0.5 }} />
                        <div style={{ fontSize: '16px', fontWeight: 500 }}>No files yet</div>
                        <div style={{ fontSize: '13px', marginTop: '5px' }}>Import or scan to begin</div>
                    </div>
                ) : (
                    <div style={{ padding: '15px' }}>
                        {files.map((file: FileMetadata, idx: number) => (
                            <div key={idx} style={{ 
                                padding: '12px', 
                                borderBottom: idx < files.length - 1 ? '1px solid #f0f0f0' : 'none',
                                display: 'flex',
                                justifyContent: 'space-between',
                                alignItems: 'center'
                            }}>
                                <div style={{ flex: 1, display: 'flex', alignItems: 'center', gap: '12px' }}>
                                    <FileText size={20} color="#666" />
                                    <div>
                                        <div style={{ fontWeight: 500, fontSize: '14px' }}>{file.name}</div>
                                        <div style={{ fontSize: '12px', color: '#999', marginTop: '2px' }}>
                                            {formatBytes(file.size)} • {file.originalPath ? 'Imported' : 'Scanned'}
                                        </div>
                                    </div>
                                </div>
                                <div style={{ display: 'flex', gap: '8px' }}>
                                    <IconButton icon={<Eye size={18} />} onClick={() => onPreview(file.name)} title="Preview" />
                                    <IconButton icon={<Printer size={18} />} onClick={() => onPrint(file.name)} title="Print" />
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
}

// Owner View Component
function OwnerView({ residueFiles, hasScanned, cleanupReport, auditLogs, isProcessing, onResidueScan, onResidueCleanup, onRefreshLogs, formatDate }: any) {
    const [activeTab, setActiveTab] = useState<'residue' | 'logs' | 'trust'>('residue');

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
            
            <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                <Settings size={24} />
                <h2 style={{ margin: 0, fontSize: '20px', fontWeight: 600 }}>Owner Dashboard</h2>
            </div>

            {/* Tabs */}
            <div style={{ display: 'flex', gap: '10px', borderBottom: '2px solid #e0e0e0' }}>
                <Tab label="Residue Guard" active={activeTab === 'residue'} onClick={() => setActiveTab('residue')} />
                <Tab label="System Logs" active={activeTab === 'logs'} onClick={() => setActiveTab('logs')} />
                <Tab label="Trust Info" active={activeTab === 'trust'} onClick={() => setActiveTab('trust')} />
            </div>

            {/* Tab Content */}
            {activeTab === 'residue' && (
                <div style={{ background: 'white', padding: '20px', borderRadius: '8px', border: '1px solid #e0e0e0' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '15px', alignItems: 'center' }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                            <Shield size={20} />
                            <h3 style={{ margin: 0, fontSize: '16px', fontWeight: 600 }}>Data Residue Scanner</h3>
                        </div>
                        <button onClick={onResidueScan} disabled={isProcessing} style={{ padding: '8px 16px', cursor: 'pointer', border: '1px solid #ccc', borderRadius: '6px', background: 'white', display: 'flex', alignItems: 'center', gap: '8px', fontWeight: 500 }}>
                            <Activity size={16} />
                            {isProcessing ? 'Scanning...' : 'Scan Now'}
                        </button>
                    </div>
                    
                    {cleanupReport && (
                        <div style={{ padding: '12px', background: '#d4edda', borderRadius: '6px', marginBottom: '10px', display: 'flex', alignItems: 'center', gap: '10px' }}>
                            <CheckCircle size={18} color="#28a745" />
                            {cleanupReport}
                        </div>
                    )}

                    {hasScanned && (
                        residueFiles.length === 0 ? (
                            <div style={{ textAlign: 'center', padding: '40px', color: '#28a745' }}>
                                <CheckCircle size={48} style={{ margin: '0 auto 15px' }} />
                                <div style={{ fontSize: '18px', fontWeight: 600 }}>System Clean</div>
                                <div style={{ fontSize: '14px', marginTop: '5px', opacity: 0.8 }}>No risky files detected</div>
                            </div>
                        ) : (
                            <div>
                                <div style={{ padding: '15px', background: '#fff3cd', borderRadius: '6px', marginBottom: '15px' }}>
                                    <div style={{ fontWeight: 600, marginBottom: '10px', display: 'flex', alignItems: 'center', gap: '10px' }}>
                                        <AlertTriangle size={20} color="#856404" />
                                        {residueFiles.length} Risk Files Detected
                                    </div>
                                    <button onClick={onResidueCleanup} style={{ padding: '10px 20px', background: '#dc3545', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 600, display: 'flex', alignItems: 'center', gap: '8px' }}>
                                        <Trash2 size={18} />
                                        Secure Cleanup All
                                    </button>
                                </div>
                                <div style={{ maxHeight: '200px', overflowY: 'auto', fontSize: '13px' }}>
                                    {residueFiles.map((f: ResidueFile, i: number) => (
                                        <div key={i} style={{ padding: '10px', borderBottom: '1px solid #f0f0f0', display: 'flex', alignItems: 'center', gap: '10px' }}>
                                            <FileText size={16} color="#666" />
                                            {f.name} <span style={{ color: '#999', fontSize: '12px' }}>({f.location})</span>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        )
                    )}
                </div>
            )}

            {activeTab === 'logs' && (
                <div style={{ background: 'white', padding: '20px', borderRadius: '8px', border: '1px solid #e0e0e0' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '15px', alignItems: 'center' }}>
                        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                            <Database size={20} />
                            <h3 style={{ margin: 0, fontSize: '16px', fontWeight: 600 }}>Audit Trail (Local Only)</h3>
                        </div>
                        <button onClick={onRefreshLogs} style={{ padding: '8px 16px', cursor: 'pointer', border: '1px solid #ccc', borderRadius: '6px', background: 'white', display: 'flex', alignItems: 'center', gap: '8px', fontWeight: 500 }}>
                            <RefreshCw size={16} />
                            Refresh
                        </button>
                    </div>
                    <div style={{ maxHeight: '400px', overflowY: 'auto', fontSize: '13px', fontFamily: 'monospace' }}>
                        {auditLogs.length === 0 ? (
                            <div style={{ textAlign: 'center', padding: '40px', color: '#999' }}>
                                <Activity size={48} style={{ margin: '0 auto 15px', opacity: 0.3 }} />
                                <div>No events logged yet</div>
                            </div>
                        ) : (
                            auditLogs.map((log: AuditEntry, i: number) => (
                                <div key={i} style={{ padding: '12px', borderBottom: '1px solid #f0f0f0', display: 'flex', gap: '15px', alignItems: 'center' }}>
                                    <div style={{ color: '#999', minWidth: '150px', fontSize: '12px' }}>{formatDate(log.timestamp)}</div>
                                    <div style={{ fontWeight: 600, minWidth: '130px', color: log.type.includes('FAILURE') ? '#dc3545' : log.type.includes('SUCCESS') ? '#28a745' : '#333', fontSize: '12px' }}>
                                        {log.type}
                                    </div>
                                    <div style={{ flex: 1, color: '#666', fontSize: '12px' }}>{log.details}</div>
                                </div>
                            ))
                        )}
                    </div>
                </div>
            )}

            {activeTab === 'trust' && <TrustExplanation />}
        </div>
    );
}

// Trust Explanation Component
function TrustExplanation() {
    return (
        <div style={{ background: 'white', padding: '30px', borderRadius: '8px', border: '1px solid #e0e0e0' }}>
            <h2 style={{ margin: '0 0 25px 0', fontSize: '22px', fontWeight: 600 }}>How Your Data Is Protected</h2>
            
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '25px' }}>
                <TrustStep icon={<Lock size={40} />} title="Isolated Session" text="Files stay in a secure workspace, never touching Desktop or Downloads" />
                <TrustStep icon={<Clock size={40} />} title="Auto-Expire" text="Sessions end automatically after 5 minutes of inactivity" />
                <TrustStep icon={<Trash2 size={40} />} title="Military Wipe" text="Data is cryptographically overwritten before deletion" />
                <TrustStep icon={<Shield size={40} />} title="Zero Residue" text="Both session copies and original files are destroyed" />
            </div>

            <div style={{ marginTop: '30px', padding: '15px', background: '#f8f9fa', borderRadius: '6px', fontSize: '13px', color: '#666', display: 'flex', alignItems: 'center', gap: '10px' }}>
                <Database size={18} />
                <div><strong>Local-Only:</strong> All logs and data stay on this PC. Nothing is uploaded to the cloud.</div>
            </div>
        </div>
    );
}

function TrustStep({ icon, title, text }: { icon: React.ReactNode, title: string, text: string }) {
    return (
        <div style={{ textAlign: 'center' }}>
            <div style={{ marginBottom: '12px', color: '#1a1a1a', display: 'flex', justifyContent: 'center' }}>{icon}</div>
            <div style={{ fontWeight: 600, marginBottom: '8px', fontSize: '15px' }}>{title}</div>
            <div style={{ fontSize: '13px', color: '#666', lineHeight: '1.5' }}>{text}</div>
        </div>
    );
}

function InfoCard({ icon, label, value }: { icon: React.ReactNode, label: string, value: string }) {
    return (
        <div style={{ flex: 1, background: 'white', padding: '18px', borderRadius: '8px', border: '1px solid #e0e0e0', textAlign: 'center' }}>
            <div style={{ marginBottom: '8px', color: '#666', display: 'flex', justifyContent: 'center' }}>{icon}</div>
            <div style={{ fontSize: '11px', color: '#999', textTransform: 'uppercase', marginBottom: '6px', fontWeight: 600, letterSpacing: '0.5px' }}>{label}</div>
            <div style={{ fontSize: '20px', fontWeight: 600 }}>{value}</div>
        </div>
    );
}

function ActionButton({ icon, label, onClick, disabled, danger }: any) {
    return (
        <button 
            onClick={onClick}
            disabled={disabled}
            style={{
                padding: '15px 25px',
                fontSize: '14px',
                fontWeight: 600,
                cursor: disabled ? 'not-allowed' : 'pointer',
                backgroundColor: disabled ? '#e0e0e0' : danger ? '#dc3545' : '#1a1a1a',
                color: disabled ? '#999' : 'white',
                border: 'none',
                borderRadius: '6px',
                display: 'flex',
                alignItems: 'center',
                gap: '10px',
                transition: 'all 0.2s'
            }}
        >
            {icon} {label}
        </button>
    );
}

function IconButton({ icon, onClick, title }: any) {
    return (
        <button 
            onClick={onClick}
            title={title}
            style={{ background: 'none', border: '1px solid #ddd', borderRadius: '6px', cursor: 'pointer', padding: '8px 12px', display: 'flex', alignItems: 'center', justifyContent: 'center', transition: 'all 0.2s' }}>
            {icon}
        </button>
    );
}

function Tab({ label, active, onClick }: any) {
    return (
        <button 
            onClick={onClick}
            style={{
                padding: '12px 20px',
                background: 'none',
                border: 'none',
                borderBottom: active ? '3px solid #1a1a1a' : '3px solid transparent',
                cursor: 'pointer',
                fontWeight: active ? 600 : 500,
                color: active ? '#1a1a1a' : '#666',
                fontSize: '14px',
                transition: 'all 0.2s'
            }}
        >
            {label}
        </button>
    );
}
